+      (trimmed.startsWith('yarnPath:') ||
+        trimmed.startsWith('nodeLinker:') ||
+        trimmed.startsWith('plugins:'))
+    ) {
+      inBlockToRemove = true;
+      blockIndent = indent;
+      continue;
+    }
+
+    result.push(line);
+  }
+
+  result.push('nodeLinker: node-modules');
+
+  return result.join('\n');
+}

